// Compute merge base with the default branch (needed for session filtering in resume).
// This is done before the HEAD fast-path because the merge base is needed even when
// HEAD itself has the checkpoint.
defaultBranch := getDefaultBranchFromRemote(repo)
if defaultBranch == "" {
	// Fallback: try common names
	for _, name := range []string{"main", "master"} {
		if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
			defaultBranch = name
			break
		}
	}
}

// Compute merge base hash (best-effort, nil if unavailable)
var mergeBaseHash *plumbing.Hash
if defaultBranch != "" && defaultBranch != branchName {
	if defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true); err == nil {
		if defaultCommit, err := repo.CommitObject(defaultRef.Hash()); err == nil {
			if mergeBase, err := headCommit.MergeBase(defaultCommit); err == nil && len(mergeBase) > 0 {
				mergeBaseHash = &mergeBase[0].Hash
			}
		}
	}
}

// First, check if HEAD itself has a checkpoint (most common case)
if cpID, found := trailers.ParseCheckpoint(headCommit.Message); found {
	result.checkpointID = cpID
	result.commitHash = head.Hash().String()
	result.commitMessage = headCommit.Message
	result.newerCommitsExist = false
	result.mergeBaseHash = mergeBaseHash
	return result, nil
}

// HEAD doesn't have a checkpoint - find branch-only commits
// If we can't find a default branch, or we're on it, just walk all commits
if defaultBranch == "" || defaultBranch == branchName {
	return findCheckpointInHistory(headCommit, nil), nil
}

if mergeBaseHash == nil {
	// No merge base found, fall back to walking all commits
	return findCheckpointInHistory(headCommit, nil), nil
}

// Walk from HEAD to merge base, looking for checkpoint
result = findCheckpointInHistory(headCommit, mergeBaseHash)
result.mergeBaseHash = mergeBaseHash
return result, nil

