307→// createCheckpointOnMetadataBranch creates a checkpoint on the entire/checkpoints/v1 branch.
308→// Returns the checkpoint ID.
309→func createCheckpointOnMetadataBranch(t *testing.T, repo *git.Repository, sessionID string) id.CheckpointID {
310→	t.Helper()
311→
312→	checkpointID := id.MustCheckpointID("abc123def456") // Fixed ID for testing
313→
314→	// Get existing metadata branch or create it
315→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
316→		t.Fatalf("Failed to ensure metadata branch: %v", err)
317→	}
318→
319→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
320→	ref, err := repo.Reference(refName, true)
321→	if err != nil {
322→		t.Fatalf("Failed to get metadata branch ref: %v", err)
323→	}
324→
325→	parentCommit, err := repo.CommitObject(ref.Hash())
326→	if err != nil {
327→		t.Fatalf("Failed to get parent commit: %v", err)
328→	}
329→
330→	// Create metadata content
331→	metadataJSON := fmt.Sprintf(`{
332→  "checkpoint_id": %q,
333→  "session_id": %q,
334→  "created_at": "2025-01-01T00:00:00Z",
335→  "strategy": "auto-commit"
336→}`, checkpointID.String(), sessionID)
337→
338→	// Create blob for metadata
339→	blob := repo.Storer.NewEncodedObject()
340→	blob.SetType(plumbing.BlobObject)
341→	writer, err := blob.Writer()
342→	if err != nil {
343→		t.Fatalf("Failed to create blob writer: %v", err)
344→	}
345→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
346→		t.Fatalf("Failed to write blob: %v", err)
347→	}
348→	if err := writer.Close(); err != nil {
349→		t.Fatalf("Failed to close writer: %v", err)
350→	}
351→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
352→	if err != nil {
353→		t.Fatalf("Failed to store blob: %v", err)
354→	}
355→
356→	// Create session log blob
357→	logBlob := repo.Storer.NewEncodedObject()
358→	logBlob.SetType(plumbing.BlobObject)
359→	logWriter, err := logBlob.Writer()
360→	if err != nil {
361→		t.Fatalf("Failed to create log blob writer: %v", err)
362→	}
363→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
364→		t.Fatalf("Failed to write log blob: %v", err)
365→	}
366→	if err := logWriter.Close(); err != nil {
367→		t.Fatalf("Failed to close log writer: %v", err)
368→	}
369→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
370→	if err != nil {
371→		t.Fatalf("Failed to store log blob: %v", err)
372→	}
373→
374→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
375→	shardedPath := checkpointID.Path()
376→	checkpointIDStr := checkpointID.String()
377→
378→	// Create checkpoint tree with metadata and transcript files
379→	// Entries must be sorted alphabetically
380→	checkpointTree := object.Tree{
381→		Entries: []object.TreeEntry{
382→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
383→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
384→		},
385→	}
386→	checkpointTreeObj := repo.Storer.NewEncodedObject()
387→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
388→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
389→	}
390→	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
391→	if err != nil {
392→		t.Fatalf("Failed to store checkpoint tree: %v", err)
393→	}
394→
395→	// Create inner shard tree (id[2:])
396→	innerTree := object.Tree{
397→		Entries: []object.TreeEntry{
398→			{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
399→		},
400→	}
401→	innerTreeObj := repo.Storer.NewEncodedObject()
402→	if err := innerTree.Encode(innerTreeObj); err != nil {
403→		t.Fatalf("Failed to encode inner tree: %v", err)
404→	}
405→	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
406→	if err != nil {
407→		t.Fatalf("Failed to store inner tree: %v", err)
408→	}
409→
410→	// Get existing tree entries from parent
411→	parentTree, err := parentCommit.Tree()
412→	if err != nil {
413→		t.Fatalf("Failed to get parent tree: %v", err)
414→	}
415→
416→	// Build new root tree with shard bucket
417→	var rootEntries []object.TreeEntry
418→	for _, entry := range parentTree.Entries {
419→		if entry.Name != shardedPath[:2] {
420→			rootEntries = append(rootEntries, entry)
421→		}
422→	}
423→	rootEntries = append(rootEntries, object.TreeEntry{
424→		Name: checkpointIDStr[:2],
425→		Mode: filemode.Dir,
426→		Hash: innerTreeHash,
427→	})
428→
429→	rootTree := object.Tree{Entries: rootEntries}
430→	rootTreeObj := repo.Storer.NewEncodedObject()
431→	if err := rootTree.Encode(rootTreeObj); err != nil {
432→		t.Fatalf("Failed to encode root tree: %v", err)
433→	}
434→	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
435→	if err != nil {
436→		t.Fatalf("Failed to store root tree: %v", err)
437→	}
438→
439→	// Create commit on metadata branch
440→	commit := &object.Commit{
441→		Author: object.Signature{
442→			Name:  "Test",
443→			Email: "test@example.com",
444→			When:  parentCommit.Author.When,
445→		},
446→		Committer: object.Signature{
447→			Name:  "Test",
448→			Email: "test@example.com",
449→			When:  parentCommit.Author.When,
450→		},
451→		Message:      "Add checkpoint metadata",
452→		TreeHash:     rootTreeHash,
453→		ParentHashes: []plumbing.Hash{parentCommit.Hash},
454→	}
455→	commitObj := repo.Storer.NewEncodedObject()
456→	if err := commit.Encode(commitObj); err != nil {
457→		t.Fatalf("Failed to encode commit: %v", err)
458→	}
459→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
460→	if err != nil {
461→		t.Fatalf("Failed to store commit: %v", err)
462→	}
463→
464→	// Update metadata branch ref
465→	newRef := plumbing.NewHashReference(refName, commitHash)
466→	if err := repo.Storer.SetReference(newRef); err != nil {
467→		t.Fatalf("Failed to update metadata branch: %v", err)
