// createMultiSessionCheckpoint creates a multi-session checkpoint on the metadata branch.
// Uses the new CheckpointSummary format with per-session subdirectories.
// Returns the checkpoint ID.
func createMultiSessionCheckpoint(
	t *testing.T,
	repo *git.Repository,
	checkpointIDStr string,
	sessions []struct {
		SessionID string
		Agent     string
		CreatedAt string // RFC3339 timestamp
	},
) id.CheckpointID {
	t.Helper()

	checkpointID := id.MustCheckpointID(checkpointIDStr)

	// Ensure metadata branch exists
	if err := strategy.EnsureMetadataBranch(repo); err != nil {
		t.Fatalf("Failed to ensure metadata branch: %v", err)
	}

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		t.Fatalf("Failed to get metadata branch ref: %v", err)
	}

	parentCommit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		t.Fatalf("Failed to get parent commit: %v", err)
	}

	shardPrefix := checkpointIDStr[:2]
	shardSuffix := checkpointIDStr[2:]

	// Build per-session trees and CheckpointSummary sessions array
	var sessionFilePaths []string // JSON array entries for sessions
	var sessionTreeEntries []object.TreeEntry

	for i, sess := range sessions {
		subdir := fmt.Sprintf("%d", i)

		// Session metadata.json (CommittedMetadata)
		sessionMetaJSON := fmt.Sprintf(`{
  "checkpoint_id": %q,
  "session_id": %q,
  "agent": %q,
  "created_at": %q,
  "strategy": "manual-commit",
  "checkpoints_count": 1,
  "files_touched": []
}`, checkpointIDStr, sess.SessionID, sess.Agent, sess.CreatedAt)

		metaBlobHash := storeBlob(t, repo, []byte(sessionMetaJSON))
		logBlobHash := storeBlob(t, repo, []byte(`{"type":"test","session":"`+sess.SessionID+`"}`))

		// Create session subdirectory tree
		sessionTree := object.Tree{
			Entries: []object.TreeEntry{
				{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
				{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metaBlobHash},
			},
		}
		sessionTreeObj := repo.Storer.NewEncodedObject()
		if err := sessionTree.Encode(sessionTreeObj); err != nil {
			t.Fatalf("Failed to encode session tree: %v", err)
		}
		sessionTreeHash, err := repo.Storer.SetEncodedObject(sessionTreeObj)
		if err != nil {
			t.Fatalf("Failed to store session tree: %v", err)
		}

		sessionTreeEntries = append(sessionTreeEntries, object.TreeEntry{
			Name: subdir,
			Mode: filemode.Dir,
			Hash: sessionTreeHash,
		})

		// Build session file paths for CheckpointSummary
		basePath := fmt.Sprintf("/%s/%s/%s", shardPrefix, shardSuffix, subdir)
		sessionFilePaths = append(sessionFilePaths, fmt.Sprintf(
			`{"metadata":"%s/%s","transcript":"%s/%s","prompt":"%s/%s","content_hash":"","context":""}`,
			basePath, paths.MetadataFileName,
			basePath, paths.TranscriptFileName,
			basePath, "prompt.txt",
		))
	}

	// Create root-level metadata.json (CheckpointSummary)
	sessionsJSON := "[" + joinStrings(sessionFilePaths, ",") + "]"
	summaryJSON := fmt.Sprintf(`{
  "checkpoint_id": %q,
  "strategy": "manual-commit",
  "checkpoints_count": 1,
  "files_touched": [],
  "sessions": %s
}`, checkpointIDStr, sessionsJSON)

	summaryBlobHash := storeBlob(t, repo, []byte(summaryJSON))

	// Build checkpoint tree: metadata.json + session subdirs
	checkpointEntries := []object.TreeEntry{
		{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: summaryBlobHash},
	}
	checkpointEntries = append(checkpointEntries, sessionTreeEntries...)

	checkpointTree := object.Tree{Entries: checkpointEntries}
	checkpointTreeObj := repo.Storer.NewEncodedObject()
	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
		t.Fatalf("Failed to encode checkpoint tree: %v", err)
	}
	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
	if err != nil {
		t.Fatalf("Failed to store checkpoint tree: %v", err)
	}

	// Create shard trees
	innerTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
		},
	}
	innerTreeObj := repo.Storer.NewEncodedObject()
	if err := innerTree.Encode(innerTreeObj); err != nil {
		t.Fatalf("Failed to encode inner tree: %v", err)
	}
	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
	if err != nil {
		t.Fatalf("Failed to store inner tree: %v", err)
	}

	// Get existing tree entries from parent and merge
	parentTree, err := parentCommit.Tree()
	if err != nil {
		t.Fatalf("Failed to get parent tree: %v", err)
	}

	var rootEntries []object.TreeEntry
	for _, entry := range parentTree.Entries {
		if entry.Name != shardPrefix {
			rootEntries = append(rootEntries, entry)
		}
	}
	rootEntries = append(rootEntries, object.TreeEntry{
		Name: shardPrefix,
		Mode: filemode.Dir,
		Hash: innerTreeHash,
	})

	rootTree := object.Tree{Entries: rootEntries}
	rootTreeObj := repo.Storer.NewEncodedObject()
	if err := rootTree.Encode(rootTreeObj); err != nil {
		t.Fatalf("Failed to encode root tree: %v", err)
	}
	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
	if err != nil {
		t.Fatalf("Failed to store root tree: %v", err)
	}

	// Create commit on metadata branch
	commitObj := &object.Commit{
		Author: object.Signature{
			Name:  "Test",
			Email: "test@example.com",
			When:  parentCommit.Author.When,
		},
		Committer: object.Signature{
			Name:  "Test",
			Email: "test@example.com",
			When:  parentCommit.Author.When,
		},
		Message:      fmt.Sprintf("Checkpoint: %s", checkpointIDStr),
		TreeHash:     rootTreeHash,
		ParentHashes: []plumbing.Hash{parentCommit.Hash},
	}
	encodedCommit := repo.Storer.NewEncodedObject()
	if err := commitObj.Encode(encodedCommit); err != nil {
		t.Fatalf("Failed to encode commit: %v", err)
	}
	commitHash, err := repo.Storer.SetEncodedObject(encodedCommit)
	if err != nil {
		t.Fatalf("Failed to store commit: %v", err)
	}

	// Update metadata branch ref
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		t.Fatalf("Failed to update metadata branch: %v", err)
	}

	return checkpointID
}

// storeBlob stores a blob in the repository and returns its hash.
func storeBlob(t *testing.T, repo *git.Repository, data []byte) plumbing.Hash {
	t.Helper()
	blob := repo.Storer.NewEncodedObject()
	blob.SetType(plumbing.BlobObject)
	writer, err := blob.Writer()
	if err != nil {
		t.Fatalf("Failed to create blob writer: %v", err)
	}
	if _, err := writer.Write(data); err != nil {
		t.Fatalf("Failed to write blob: %v", err)
	}
	if err := writer.Close(); err != nil {
		t.Fatalf("Failed to close writer: %v", err)
	}
	hash, err := repo.Storer.SetEncodedObject(blob)
	if err != nil {
		t.Fatalf("Failed to store blob: %v", err)
	}
	return hash
}

// joinStrings joins strings with a separator (avoids importing strings in test).
func joinStrings(strs []string, sep string) string {
	result := ""
	for i, s := range strs {
		if i > 0 {
			result += sep
		}
		result += s
	}
	return result
}

// makeCommitWithCheckpoint creates a commit on the current branch with a checkpoint trailer.
func makeCommitWithCheckpoint(t *testing.T, w *git.Worktree, tmpDir string, checkpointID id.CheckpointID, filename, content, message string) plumbing.Hash {
	t.Helper()
	testFile := filepath.Join(tmpDir, filename)
	if err := os.WriteFile(testFile, []byte(content), 0o644); err != nil {
		t.Fatalf("Failed to write file: %v", err)
	}
	if _, err := w.Add(filename); err != nil {
		t.Fatalf("Failed to add file: %v", err)
	}
	commitMsg := fmt.Sprintf("%s\n\nEntire-Checkpoint: %s", message, checkpointID.String())
	hash, err := w.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test User",
			Email: "test@example.com",
		},
	})
	if err != nil {
		t.Fatalf("Failed to create commit: %v", err)
	}
	return hash
}

func TestFindBranchCheckpoint_MergeBaseAlwaysSet(t *testing.T) {
	// Verify that mergeBaseHash is set even when HEAD has the checkpoint (the fast-path).
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	repo, w, initialCommit := setupResumeTestRepo(t, tmpDir, false)

	// Create "main" branch at initial commit (go-git uses "master" by default,
	// but our code also checks for "main")
	mainRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("main"), initialCommit)
	if err := repo.Storer.SetReference(mainRef); err != nil {
		t.Fatalf("Failed to create main branch: %v", err)
	}

	// Create feature branch
	featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), initialCommit)
	if err := repo.Storer.SetReference(featureRef); err != nil {
		t.Fatalf("Failed to create feature branch: %v", err)
	}

	// Checkout feature branch
	if err := w.Checkout(&git.CheckoutOptions{
		Branch: plumbing.NewBranchReferenceName("feature"),
	}); err != nil {
		t.Fatalf("Failed to checkout feature: %v", err)
	}

	// Create a checkpoint on the metadata branch
	cpID := id.MustCheckpointID("aaa111bbb222")
	createCheckpointOnMetadataBranch(t, repo, "session-1")

	// Create a commit with the checkpoint trailer ON HEAD (the fast-path case)
	makeCommitWithCheckpoint(t, w, tmpDir, cpID, "feature.txt", "feature content", "Add feature")

	// Call findBranchCheckpoint
	result, err := findBranchCheckpoint(repo, "feature")
	if err != nil {
		t.Fatalf("findBranchCheckpoint() error = %v", err)
	}

	// Verify checkpoint was found
	if result.checkpointID.IsEmpty() {
		t.Fatal("findBranchCheckpoint() did not find checkpoint")
	}

	// Verify merge base was computed (the bug was that the fast-path returned without it)
	if result.mergeBaseHash == nil {
		t.Error("findBranchCheckpoint() mergeBaseHash is nil - merge base not computed in HEAD fast-path")
	} else {
		// Merge base should be the initial commit (common ancestor of feature and main)
		if *result.mergeBaseHash != initialCommit {
			t.Errorf("findBranchCheckpoint() mergeBaseHash = %s, want %s (initial commit)",
				result.mergeBaseHash.String()[:7], initialCommit.String()[:7])
		}
	}
}

func TestFindMainSessionIDs_ReturnsSessionsFromMain(t *testing.T) {
	// When main has a checkpoint with sessions, findMainSessionIDs should return those session IDs.
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	repo, w, initialCommit := setupResumeTestRepo(t, tmpDir, false)

	// Create a commit on main with a checkpoint trailer
	mainCpID := id.MustCheckpointID("main11111111")
	makeCommitWithCheckpoint(t, w, tmpDir, mainCpID, "main-work.txt", "main content", "Main work")

	// Get the main commit hash (current HEAD after the checkpoint commit)
	mainHead, err := repo.Head()
	if err != nil {
		t.Fatalf("Failed to get HEAD: %v", err)
	}

	// Create multi-session checkpoint on metadata branch for main's checkpoint
	createMultiSessionCheckpoint(t, repo, mainCpID.String(), []struct {
		SessionID string
		Agent     string
		CreatedAt string
	}{
		{SessionID: "session-A", Agent: "Claude Code", CreatedAt: "2025-01-01T10:00:00Z"},
		{SessionID: "session-B", Agent: "Claude Code", CreatedAt: "2025-01-01T11:00:00Z"},
	})

	// The merge base is the main commit itself (feature branched from here)
	_ = initialCommit
	mergeBase := mainHead.Hash()

	// Get metadata tree
	metadataTree, err := strategy.GetMetadataBranchTree(repo)
	if err != nil {
		t.Fatalf("Failed to get metadata tree: %v", err)
	}

	// Call findMainSessionIDs
	result := findMainSessionIDs(repo, &mergeBase, metadataTree)

	if result == nil {
		t.Fatal("findMainSessionIDs() returned nil, expected session IDs")
	}

	if !result["session-A"] {
		t.Error("findMainSessionIDs() missing session-A")
	}
	if !result["session-B"] {
		t.Error("findMainSessionIDs() missing session-B")
	}
	if len(result) != 2 {
		t.Errorf("findMainSessionIDs() returned %d sessions, want 2", len(result))
	}
}

