func TestFindBranchCheckpoint_FullFilteringScenario(t *testing.T) {
	// Full scenario: main has sessions A and B, branch adds session C.
	// findMainSessionIDs should return A and B, so resume can filter them out.
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	repo, w, _ := setupResumeTestRepo(t, tmpDir, false)

	// 1. Create a commit on main with checkpoint C1 (sessions A and B)
	mainCpID := id.MustCheckpointID("aaa111bbb333")
	makeCommitWithCheckpoint(t, w, tmpDir, mainCpID, "main-work.txt", "main content", "Main work with sessions")

	// Record main HEAD (this will be the merge base)
	mainHead, err := repo.Head()
	if err != nil {
		t.Fatalf("Failed to get main HEAD: %v", err)
	}

	// Create multi-session checkpoint for main (sessions A and B)
	createMultiSessionCheckpoint(t, repo, mainCpID.String(), []struct {
		SessionID string
		Agent     string
		CreatedAt string
	}{
		{SessionID: "session-A", Agent: "Claude Code", CreatedAt: "2025-01-01T10:00:00Z"},
		{SessionID: "session-B", Agent: "Claude Code", CreatedAt: "2025-01-01T11:00:00Z"},
	})

	// 2. Create a "main" branch pointing to current HEAD
	mainRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("main"), mainHead.Hash())
	if err := repo.Storer.SetReference(mainRef); err != nil {
		t.Fatalf("Failed to create main branch: %v", err)
	}

	// 3. Create feature branch and commit with checkpoint C2 (sessions A, B, and C)
	featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), mainHead.Hash())
	if err := repo.Storer.SetReference(featureRef); err != nil {
		t.Fatalf("Failed to create feature branch: %v", err)
	}

	if err := w.Checkout(&git.CheckoutOptions{
		Branch: plumbing.NewBranchReferenceName("feature"),
	}); err != nil {
		t.Fatalf("Failed to checkout feature: %v", err)
	}

	branchCpID := id.MustCheckpointID("bbb222ccc444")
	makeCommitWithCheckpoint(t, w, tmpDir, branchCpID, "feature-work.txt", "feature content", "Feature work with new session")

	// Create multi-session checkpoint for branch (all 3 sessions: A, B, C)
	createMultiSessionCheckpoint(t, repo, branchCpID.String(), []struct {
		SessionID string
		Agent     string
		CreatedAt string
	}{
		{SessionID: "session-A", Agent: "Claude Code", CreatedAt: "2025-01-01T10:00:00Z"},
		{SessionID: "session-B", Agent: "Claude Code", CreatedAt: "2025-01-01T11:00:00Z"},
		{SessionID: "session-C", Agent: "Claude Code", CreatedAt: "2025-01-02T09:00:00Z"},
	})

	// 4. Call findBranchCheckpoint to get the branch checkpoint and merge base
	result, err := findBranchCheckpoint(repo, "feature")
	if err != nil {
		t.Fatalf("findBranchCheckpoint() error = %v", err)
	}

	if result.checkpointID != branchCpID {
		t.Fatalf("findBranchCheckpoint() checkpoint = %s, want %s", result.checkpointID, branchCpID)
	}

	if result.mergeBaseHash == nil {
		t.Fatal("findBranchCheckpoint() mergeBaseHash is nil")
	}

	// 5. Call findMainSessionIDs
	metadataTree, err := strategy.GetMetadataBranchTree(repo)
	if err != nil {
		t.Fatalf("Failed to get metadata tree: %v", err)
	}

	mainSessions := findMainSessionIDs(repo, result.mergeBaseHash, metadataTree)
	if mainSessions == nil {
		t.Fatal("findMainSessionIDs() returned nil, expected sessions from main")
	}

	// Should have sessions A and B from main
	if !mainSessions["session-A"] {
		t.Error("findMainSessionIDs() missing session-A")
	}
	if !mainSessions["session-B"] {
		t.Error("findMainSessionIDs() missing session-B")
	}
	// Session C should NOT be in main's sessions
	if mainSessions["session-C"] {
		t.Error("findMainSessionIDs() should not include session-C (branch-only)")
	}
}

