case "session.created": {
  const session = (event as any).properties?.info
  if (!session?.id) break
  // End the previous session if switching — OpenCode doesn't fire
  // session.deleted on exit or session switch, so without this,
  // the old session stays in "active" phase forever.
  if (currentSessionID && currentSessionID !== session.id) {
    await callHook("session-end", {
      session_id: currentSessionID,
    })
  }
  seenUserMessages.clear()
  messageStore.clear()
  currentSessionID = session.id
  await callHook("session-start", {
    session_id: session.id,
  })
  break
}

